CREATE VIEW v_client_district AS SELECT client.client_id, client.gender, client.birth_date, district.district_id, district.A2 AS district_name, district.A3 AS region, district.A4 AS no_of_inhabitants, district.A11 AS avg_salary, client.district_id AS client_district_id, district.A12, district.A13, district.A15 FROM client LEFT JOIN district ON client.district_id = district.district_id;

CREATE VIEW v_account_district AS SELECT account.account_id, account.frequency, account.date AS account_created_date, district.district_id, district.A2 AS district_name, district.A3 AS region, district.A11 AS avg_salary, account.district_id AS account_district_id, district.A4, district.A12, district.A13, district.A15 FROM account LEFT JOIN district ON account.district_id = district.district_id;

CREATE VIEW v_account_loan AS SELECT account.account_id, account.frequency, account.date AS account_date, loan.loan_id, loan.date AS loan_date, loan.amount AS loan_amount, loan.duration AS loan_duration, loan.payments AS loan_payments, loan.status AS loan_status, account.district_id, loan.account_id AS loan_account_id FROM account LEFT JOIN loan ON account.account_id = loan.account_id;

CREATE VIEW v_account_client_disp_district AS SELECT account.account_id, account.district_id, account.frequency, account.date, district.district_id AS district_district_id, district.A2, district.A3, district.A4, district.A11, district.A12, district.A13, district.A15, disp.disp_id, disp.client_id, disp.account_id AS disp_account_id, disp.type, client.client_id AS client_client_id, client.gender, client.birth_date, client.district_id AS client_district_id FROM account INNER JOIN district ON account.district_id = district.district_id INNER JOIN disp ON account.account_id = disp.account_id INNER JOIN client ON disp.client_id = client.client_id;

CREATE VIEW v_account_client_disp_loan AS SELECT account.account_id, account.district_id, account.frequency, account.date, loan.account_id AS loan_account_id, loan.date AS loan_date, loan.amount, loan.duration, loan.status, disp.disp_id, disp.client_id, disp.account_id AS disp_account_id, disp.type, client.client_id AS client_client_id, client.gender, client.birth_date, client.district_id AS client_district_id FROM account INNER JOIN loan ON account.account_id = loan.account_id INNER JOIN disp ON account.account_id = disp.account_id INNER JOIN client ON disp.client_id = client.client_id;

CREATE VIEW v_account_client_disp_trans AS SELECT account.account_id, account.district_id, account.frequency, account.date, disp.disp_id, disp.client_id, disp.account_id AS disp_account_id, disp.type, trans.trans_id, trans.account_id AS trans_account_id, trans.date AS trans_date, trans.type AS trans_type, trans.operation, trans.amount, trans.balance, client.client_id AS client_client_id, client.gender, client.birth_date, client.district_id AS client_district_id FROM account INNER JOIN disp ON account.account_id = disp.account_id INNER JOIN trans ON account.account_id = trans.account_id INNER JOIN client ON disp.client_id = client.client_id;

CREATE VIEW v_account_disp_district AS SELECT account.account_id, account.district_id, account.frequency, account.date, district.district_id AS district_district_id, district.A2, district.A3, district.A4, district.A11, district.A12, district.A13, district.A15, disp.disp_id, disp.client_id, disp.account_id AS disp_account_id, disp.type FROM account INNER JOIN district ON account.district_id = district.district_id INNER JOIN disp ON account.account_id = disp.account_id;

CREATE VIEW v_account_district_loan AS SELECT account.account_id, account.district_id, account.frequency, account.date, loan.account_id AS loan_account_id, loan.date AS loan_date, loan.amount, loan.duration, loan.status, district.district_id AS district_district_id, district.A2, district.A3, district.A4, district.A11, district.A12, district.A13, district.A15 FROM account INNER JOIN loan ON account.account_id = loan.account_id INNER JOIN district ON account.district_id = district.district_id;

CREATE VIEW v_account_district_trans AS SELECT account.account_id, account.district_id, account.frequency, account.date, district.district_id AS district_district_id, district.A2, district.A3, district.A4, district.A11, district.A12, district.A13, district.A15, trans.trans_id, trans.account_id AS trans_account_id, trans.date AS trans_date, trans.type, trans.operation, trans.amount, trans.balance FROM account INNER JOIN district ON account.district_id = district.district_id INNER JOIN trans ON account.account_id = trans.account_id;

CREATE VIEW v_account_loan_trans AS SELECT account.account_id, account.district_id, account.frequency, account.date, loan.account_id AS loan_account_id, loan.date AS loan_date, loan.amount, loan.duration, loan.status, trans.trans_id, trans.account_id AS trans_account_id, trans.date AS trans_date, trans.type, trans.operation, trans.amount AS trans_amount, trans.balance FROM account INNER JOIN loan ON account.account_id = loan.account_id INNER JOIN trans ON account.account_id = trans.account_id;

CREATE VIEW v_account_trans AS SELECT account.account_id, account.district_id, account.frequency, account.date, trans.trans_id, trans.account_id AS trans_account_id, trans.date AS trans_date, trans.type, trans.operation, trans.amount, trans.balance FROM account INNER JOIN trans ON account.account_id = trans.account_id;

CREATE VIEW v_card_client_disp AS SELECT card.disp_id, card.type, disp.disp_id AS disp_disp_id, disp.client_id, disp.account_id, disp.type AS disp_type, client.client_id AS client_client_id, client.gender, client.birth_date, client.district_id FROM card INNER JOIN disp ON card.disp_id = disp.disp_id INNER JOIN client ON disp.client_id = client.client_id;

CREATE VIEW v_order AS SELECT "order".account_id, "order".amount, "order".k_symbol FROM "order";

CREATE VIEW v_trans AS SELECT trans.trans_id, trans.account_id, trans.date, trans.type, trans.operation, trans.amount, trans.balance FROM trans;
